def normalizar_situaciones_revista(apps, schema_editor):
    Designacion = apps.get_model('personal', 'Designacion')
    equivalencias = {
        'Titular': 'TIT',
        'Interino': 'INT',
        'Suplente': 'SUP',
    }
    for anterior, nuevo in equivalencias.items():
        Designacion.objects.filter(
            situacion_revista__iexact=anterior,
        ).update(situacion_revista=nuevo)


